commands.command:
python3 - <<'PY'
from pathlib import Path
p = Path('packages/shelly-client/src/__tests__/plugsUi.test.ts')
s = p.read_text()
anchor = "  it('returns a clean unsupported state without calling PLUGS_UI', async () => {
"
insert = "  it('reads config without requiring mutation support', async () => {
    const transport = new RecordingTransport([
      { ok: true, value: { methods: ['PLUGS_UI.GetConfig'] } },
      { ok: true, value: fullConfig }
    ]);
    const client = new RpcShellyPlugsUiClient(transport);

    await expect(client.readConfig()).resolves.toMatchObject({
      ok: true,
      value: { supported: true, config: fullConfig }
    });
    expect(transport.requests).toEqual([
      { method: 'Shelly.ListMethods' },
      { method: 'PLUGS_UI.GetConfig' }
    ]);
  });

" + anchor
if anchor not in s:
    raise SystemExit('anchor not found')
p.write_text(s.replace(anchor, insert, 1))
PY

